const basePath = `${window.location.protocol}//${window.location.hostname}`;

const config = {
    development: {
        backendAPI: `http://localhost:8080/api`,
    },
    production: {
        backendAPI: `${basePath}/api`
    }
}

export default config[process.env.NODE_ENV];



