import React, { Component } from 'react';
import AppBar from '@material-ui/core/AppBar';
import Toolbar from '@material-ui/core/Toolbar';
import Typography from '@material-ui/core/Typography';
import Tabs from '@material-ui/core/Tabs';
import Tab from '@material-ui/core/Tab';
import HomeIcon from '@material-ui/icons/Home';
import AddIcon from '@material-ui/icons/Add';
import { Link } from 'react-router-dom';
import { ImmutableLoadingBar as LoadingBar } from 'react-redux-loading-bar';
import ReduxToastr from 'react-redux-toastr';
import Button from '@material-ui/core/Button';
import PropTypes from 'prop-types';

class Layout extends Component {
  constructor(props) {
      super(props);
      this.state = {
        activeTab: 0
      }
  }

  componentDidMount() {
    switch(this.props.location.pathname) {
      case '/home': this.setState({ activeTab: 0 });
        break;
      case '/createEvent': this.setState({ activeTab: 1 });
        break;
      default : 
    }
  }

  handleTabChange = (event, value) => {
    this.setState({ activeTab: value });
  }

  render() {
    const { user } = this.props;
    const { activeTab } = this.state;
    const renderTabs = user.data ? (
      <RenderTabs activeTab={activeTab} handleTabChange={this.handleTabChange}/>
    ) : null;

    return (
      <div>
        <AppBar position="fixed">
          <Toolbar style={{ justifyContent: 'space-between' }}>
            <Typography variant="title" color="inherit">
              Chemo Cal
            </Typography>
            <div>
              {renderTabs}
            </div>
            <Button color="inherit" onClick={() => {
              this.props.logout();
              this.context && this.context.router && this.context.router.history && this.context.router.history.push('/login');
            }}>Logout</Button>
          </Toolbar>
          <LoadingBar />
        </AppBar>
        <div id='main-container' style={{marginTop: '100px'}} className='container-fluid'>
          {this.props.children}
          <ReduxToastr
            timeOut={4000}
            newestOnTop={false}
            preventDuplicates
            position="bottom-right"
            transitionIn="fadeIn"
            transitionOut="fadeOut"
            progressBar/>
        </div>
      </div>
    );
  }
}

const RenderTabs = (props) => {
  return (
    <Tabs value={props.activeTab} onChange={props.handleTabChange} centered>
      <Tab label="home" icon={<HomeIcon />} component={Link} to="/home" />
      <Tab label="event" icon={<AddIcon />} component={Link} to="/createEvent"/>
    </Tabs>
  )
}

Layout.contextTypes = {
  router: PropTypes.object
}

export default Layout;


